const input = $json.body || $json;
const resumeText = String(input.resumeText || input.resume || '').trim();
const jobText = String(input.jobDescription || input.job || '').trim();
if (!resumeText || !jobText) throw new Error('Both resumeText and jobDescription are required.');
return [{ json: { candidateName: input.candidateName || 'Candidate', jobTitle: input.jobTitle || 'Target role', resumeText, jobText, receivedAt: new Date().toISOString() } }];

const d = $json;
const stop = new Set(['the','and','for','with','that','this','from','are','you','your','will','our','have','has','job','role','work','years','using','into','about','they','their','who','what','can']);
const tokenize = s => [...new Set(String(s).toLowerCase().replace(/[^a-z0-9+#.\-\s]/g,' ').split(/\s+/).filter(w => w.length > 2 && !stop.has(w)))];
const resumeWords = new Set(tokenize(d.resumeText));
const jobWords = tokenize(d.jobText);
const matched = jobWords.filter(w => resumeWords.has(w));
const missing = jobWords.filter(w => !resumeWords.has(w));
const score = Math.min(100, Math.round(matched.length / Math.max(jobWords.length, 1) * 100));
const level = score >= 75 ? 'Strong match' : score >= 50 ? 'Moderate match' : 'Weak match';
return [{ json: { ...d, match: { score, level, matchedKeywords: matched.slice(0, 50), missingKeywords: missing.slice(0, 50), keywordCoveragePercent: score }, disclaimer: 'This automated score is a screening aid and must not be the sole basis for an employment decision.' } }];

const d = $json;
const m = d.match;
const bullets = a => a.length ? a.map(x => '- ' + x).join('
') : '- None detected.';
const reportMarkdown = `# AI Resume–Job Match Report

**Candidate:** ${d.candidateName}  
**Target role:** ${d.jobTitle}  
**Generated:** ${new Date().toISOString()}

## Match result
**${m.score}/100 — ${m.level}**

## Matched keywords
${bullets(m.matchedKeywords)}

## Potentially missing keywords
${bullets(m.missingKeywords)}

## Recommendations
- Tailor the professional summary to the target role.
- Add measurable achievements related to the job requirements.
- Add missing skills only when they accurately represent the candidate’s experience.
- Review the original documents before making a hiring decision.

## Notice
${d.disclaimer}`;
return [{ json: { ...d, reportMarkdown, reportStatus: 'ready' } }];
